package com.arjunren.hospital.entity;
import com.arjunren.hospital.domain.AppointmentStatus;import jakarta.persistence.*;import java.time.*;
@Entity@Table(name="appointments",indexes={@Index(name="appointments_doctor_start_idx",columnList="doctor_id,starts_at"),@Index(name="appointments_patient_idx",columnList="patient_id")})public class Appointment{@Id@GeneratedValue(strategy=GenerationType.IDENTITY)private Long id;@ManyToOne(optional=false,fetch=FetchType.LAZY)@JoinColumn(name="doctor_id")private DoctorProfile doctor;@ManyToOne(optional=false,fetch=FetchType.LAZY)@JoinColumn(name="patient_id")private PatientProfile patient;@Column(name="starts_at",nullable=false)private Instant startsAt;@Column(name="ends_at",nullable=false)private Instant endsAt;@Column(nullable=false,length=500)private String reason;@Enumerated(EnumType.STRING)@Column(nullable=false,length=20)private AppointmentStatus status=AppointmentStatus.SCHEDULED;@Column(length=1000)private String diagnosis;@Column(length=2000)private String treatment;@ManyToOne(optional=false,fetch=FetchType.LAZY)@JoinColumn(name="created_by")private AppUser createdBy;@Version private long version;@Column(name="created_at",nullable=false,updatable=false)private Instant createdAt=Instant.now();@Column(name="updated_at",nullable=false)private Instant updatedAt=Instant.now();protected Appointment(){}public Appointment(DoctorProfile d,PatientProfile p,Instant s,Instant e,String r,AppUser u){doctor=d;patient=p;startsAt=s;endsAt=e;reason=r;createdBy=u;}@PreUpdate void ts(){updatedAt=Instant.now();}public void cancel(){status=AppointmentStatus.CANCELLED;}public void complete(String d,String t){status=AppointmentStatus.COMPLETED;diagnosis=d;treatment=t;}public Long getId(){return id;}public DoctorProfile getDoctor(){return doctor;}public PatientProfile getPatient(){return patient;}public Instant getStartsAt(){return startsAt;}public Instant getEndsAt(){return endsAt;}public String getReason(){return reason;}public AppointmentStatus getStatus(){return status;}public String getDiagnosis(){return diagnosis;}public String getTreatment(){return treatment;}public Instant getCreatedAt(){return createdAt;}}

